/* Bass engine CRT: vertical module selector + centered reverse-video menus. */
(()=>{
 const editor=document.querySelector('#bassEditor'),tabs=editor.querySelector('.bass-tabs');
 const glyphs={voice:['Voice','M2 12C5 2 8 22 12 12S19 2 22 12'],tone:['Tone','M3 5H21M3 12H21M3 19H21M7 2V8M16 9V15M10 16V22'],fx:['Processing','M3 16L8 5L13 19L18 8L21 13'],phrase:['Phrase','M3 4H7V8H3ZM10 4H14V8H10ZM17 4H21V8H17ZM3 11H7V15H3ZM10 11H14V15H10ZM17 11H21V15H17ZM3 18H7V22H3ZM10 18H14V22H10ZM17 18H21V22H17Z'],sample:['Resample','M4 8A8 8 0 1 1 4 17M4 3V9H10M9 9V16L16 12Z']};
 const icon=path=>'<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="'+path+'"/></svg>';
 tabs.setAttribute('aria-label','Bass engine modules');tabs.setAttribute('aria-orientation','vertical');
 tabs.querySelectorAll('button').forEach(button=>{const [name,path]=glyphs[button.dataset.bassTab];button.innerHTML=icon(path);button.title=name;button.setAttribute('aria-label',name);button.setAttribute('role','tab');button.id='engine-tab-'+button.dataset.bassTab;button.setAttribute('aria-controls','engine-page-'+button.dataset.bassTab);button.dataset.crtIcon='true';});
 const heading=editor.querySelector(':scope>.sectiontitle');heading.classList.add('crt-heading');const section=document.createElement('span');section.id='crtSection';section.className='crt-section-name';heading.prepend(section);heading.childNodes.forEach(n=>{if(n.nodeType===3)n.textContent=''});
 const names={voice:'VOICE',tone:'TONE',fx:'PROCESSING',phrase:'PHRASE',sample:'RESAMPLE'};
 const actionIcons={phraseShift:['Shift phrase one step','M3 12H20M15 7L20 12L15 17'],phraseVariation:['Generate phrase variation','M3 7H7L17 17H21M17 13L21 17L17 21M3 17H7L10 14M14 10L17 7H21M17 3L21 7L17 11'],phraseClear:['Clear all phrase steps','M4 6H20M9 6V3H15V6M6 6L7 21H17L18 6M10 10V17M14 10V17'],capturePhrase:['Capture phrase audio','M12 4A8 8 0 1 0 12 20A8 8 0 1 0 12 4M12 8A4 4 0 1 0 12 16A4 4 0 1 0 12 8'],exportSample:['Export capture as WAV','M12 3V16M7 11L12 16L17 11M4 16V21H20V16']};
 function refresh(){editor.querySelectorAll('[data-page]').forEach(p=>{p.id='engine-page-'+p.dataset.page;p.setAttribute('role','tabpanel');p.setAttribute('aria-labelledby','engine-tab-'+p.dataset.page)});const active=tabs.querySelector('.active'),key=active?.dataset.bassTab||'voice',page=editor.querySelector('[data-page="'+key+'"]');const sub=page?.querySelector('.control-subtabs .active');const text='[ '+names[key]+' ]'+(sub?' / '+sub.textContent.toUpperCase():'');if(section.textContent!==text)section.textContent=text;
  editor.querySelectorAll('.control-subtabs').forEach(nav=>{nav.setAttribute('role','group');nav.querySelectorAll('button').forEach(b=>{b.title='Open '+b.textContent.trim()+' controls';});if(!nav.dataset.crtKeys){nav.dataset.crtKeys='true';nav.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const buttons=[...nav.querySelectorAll('button')],index=buttons.indexOf(document.activeElement);const next=e.key==='Home'?0:e.key==='End'?buttons.length-1:(index+(e.key==='ArrowRight'?1:-1)+buttons.length)%buttons.length;buttons[next].click();buttons[next].focus()})}});
  Object.entries(actionIcons).forEach(([id,[name,path]])=>{const b=editor.querySelector('#'+id);if(b&&!b.dataset.crtIcon){b.innerHTML=icon(path);b.title=name;b.setAttribute('aria-label',name);b.dataset.crtIcon='true';b.classList.add('crt-icon-action')}});
  editor.querySelectorAll('input,select,button').forEach(el=>{if(el.title)return;const name=el.getAttribute('aria-label')||el.labels?.[0]?.textContent?.trim()||el.textContent.trim();if(name)el.title=name;});
 }
 tabs.addEventListener('keydown',e=>{if(!['ArrowUp','ArrowDown','Home','End'].includes(e.key))return;e.preventDefault();const buttons=[...tabs.querySelectorAll('button')],index=buttons.indexOf(document.activeElement),next=e.key==='Home'?0:e.key==='End'?buttons.length-1:(index+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length;buttons[next].click();buttons[next].focus()});
 let queued=false;const schedule=()=>{if(queued)return;queued=true;queueMicrotask(()=>{queued=false;refresh()})};editor.addEventListener('click',schedule);new MutationObserver(records=>{if(records.some(r=>r.type==='attributes'&&(r.target.matches('[data-page],[data-bass-tab],.control-subtabs button'))||r.type==='childList'&&Array.from(r.addedNodes).some(n=>n.nodeType===1&&n.matches?.('.bass-page,.control-subtabs'))))schedule()}).observe(editor,{childList:true,subtree:true,attributes:true,attributeFilter:['class','hidden']});refresh();
})();

